// Each specialist page answers its own buying questions. Images remain in Showcase.
const page=(title,intro,overview,scope,steps,faq)=>({title,intro,overview,scope,steps,faq});
export const subserviceContent={
 'software-outsourcing':page('Software Development Outsourcing',
  'Software development outsourcing means an outside team builds or maintains software for you under an agreed scope. Cubusify works with clients worldwide from Surat, India, as a project team, a dedicated team or flexible support.',
  'Outsourcing fits when you know the outcome you need but not the capacity or specialist skills to deliver it in-house. It fits less well when the product direction is still unsettled and every decision needs you in the room. Separate a capacity gap from a specialist question first, then choose the arrangement that matches.',
  [['Project team','A team organised around working milestones, acceptance criteria and a scoped handover for a specific release.'],['Dedicated team','An agreed mix of roles for an ongoing roadmap, with backlog ownership, review cadence and capacity defined together.'],['Flexible support','A scoped review or specialist contribution to an existing team. Availability, access and response expectations need agreement.']],
  [['Share the product and the gap','Describe the product, the repository context, the current team and the capacity or skill you need. Separate a capacity need from a specialist technical question.'],['Agree the working arrangement','Define access, code review, working-hour overlap, ownership and acceptance checks before delivery begins. Confirm availability and onboarding needs rather than assuming every role is immediately available.'],['Build, review and hand over','Review working outcomes at agreed milestones, document decisions and plan handover so knowledge stays with your product team.']],
  [['Who owns the code?','The project agreement defines ownership and handover. We hand over the agreed code, designs and project assets to you.'],['What affects the cost of outsourcing?','Scope, integrations, content readiness, technical constraints and reviews. We agree milestones and commercial terms before development begins.'],['How do we work across time zones?','Working-hour overlap is agreed before delivery begins, together with access and review points. Cubusify is based in Surat, India and works with clients worldwide, so bring the hours you need covered.']]),
 'custom-crm':page('Custom CRM Development',
  'Build a CRM around your actual sales and service process: enquiries, customer records, follow-ups and the handoff after a deal closes.',
  'A custom CRM makes sense when an existing product forces important work into spreadsheets or cannot support your permissions and integrations. Start by comparing configuration with a custom build; a familiar off-the-shelf tool may already solve the problem.',
  [['Customer records','Agree the fields, duplicate rules and relationship history your team needs before importing existing contacts.'],['Pipeline and ownership','Define deal stages, task reminders, assignment rules and what happens when an enquiry changes owner.'],['Connected reporting','Bring agreed email, form and business-system events into a shared view with role-based access.']],
  [['Map one complete sales journey','Follow an enquiry from first contact through qualification, approval and handover. Identify missing information and decisions that currently happen outside the CRM.'],['Prototype records and permissions','Review the contact model, pipeline screens and access rules with the people who use them. Reconcile a sample migration before moving the full dataset.'],['Release with a usable handover','Test assignment, search, reporting and integrations. Agree import checks, administrator guidance and the owner of future configuration.']],
  [['Should we customise an existing CRM instead?','Often, yes. Compare licensing, workflow limitations, integration access and ongoing maintenance before commissioning custom software. A custom build needs a clear operational advantage.'],['Can we migrate our spreadsheets?','Migration depends on record quality and volume. We first map columns, identify duplicates, agree ownership and test a sample import with reconciliation checks.'],['What affects CRM development cost?','The data model, number of user roles, migration work, automation rules and external connections. Bring a sample record and pipeline to help define a focused first release.']]),
 'business-dashboards':page('Business Dashboard Development',
  'Turn disconnected reports into an operational dashboard with agreed metrics, understandable filters and a clear route from a number to the underlying record.',
  'The first dashboard decision is what a person should do differently after seeing it. We work backwards from that decision to the data sources, calculation rules and freshness the team actually needs.',
  [['Metric definitions','Document formulas, time zones, exclusions and ownership so teams interpret the same number consistently.'],['Data connections','Assess databases, exports and APIs, including missing records, refresh limits and reconciliation requirements.'],['Views and drilldowns','Plan role-specific summaries, date comparisons and source-record links instead of displaying every possible chart.']],
  [['Audit the source data','Compare a sample calculation with the current report. Record incomplete fields, duplicate events and the update frequency each source supports.'],['Validate the dashboard with its users','Prototype the highest-value decisions and test filters, empty states and unusual values with realistic sample data.'],['Release with calculation checks','Verify totals against source systems, document refresh failures and agree who maintains each metric when the business changes.']],
  [['Do we need real-time reporting?','Only if the decision depends on immediate updates. Scheduled refreshes are often simpler and less costly for daily operational reporting.'],['Can the dashboard replace our BI tool?','Sometimes the right solution is configuration in an existing BI product. Custom development is more appropriate for embedded workflows, specialised access rules or actions tied to the data.'],['How will we know the numbers are correct?','Agree reference reports and test cases before building. Reconcile totals, rounding, dates and exclusions, and display the last successful update.']]),
 'saas-platforms':page('SaaS Platform Development',
  'Plan and build the first working version of a subscription software platform, from account setup and its core workflow to tenant permissions and administration.',
  'This service focuses on creating a new platform. For an existing SaaS product that needs release capacity or architectural improvements, explore SaaS engineering. A first platform should prove one repeatable customer workflow before expanding into a broad feature suite.',
  [['Tenant and account model','Define organisations, memberships, invitation rules and the boundaries between each customer’s records.'],['Core customer workflow','Design the task customers subscribe to complete, including onboarding, empty states and support access.'],['Subscriptions and operations','Scope billing integration, plan entitlements, account closure and administrator tools around the chosen commercial model.']],
  [['Define the customer and subscription','Identify who buys, who uses the product and what belongs in each plan. Choose the first workflow and evidence that would justify further investment.'],['Build one tenant-aware journey','Implement the essential experience with explicit access boundaries, representative test accounts and useful usage events.'],['Prepare a controlled first release','Check tenant isolation, billing transitions and recovery procedures. Plan support ownership and learn from a small initial customer group.']],
  [['Is a SaaS platform the same as an MVP?','A SaaS product may begin with an MVP, but not every MVP needs subscriptions or multiple tenants. Choose the smallest delivery model that tests the business assumption.'],['Does every customer need a separate database?','Not necessarily. Isolation, operating cost, reporting and customer requirements determine the architecture; the choice needs explicit tradeoffs.'],['What should we prepare before discovery?','Bring the customer workflow, proposed pricing model, user roles and any existing prototype. Mark assumptions separately from validated customer needs.']]),
 'business-websites':page('Business Website Development',
  'Create a business website that explains your offer, makes services easy to find and helps visitors send a useful enquiry from any screen.',
  'A brochure website succeeds when the right visitor understands who you help, what you deliver and why to contact you. Content, page structure and enquiry handling belong in the scope alongside the visual design.',
  [['Service and page structure','Map the homepage, service pages, proof and contact journey around the questions a prospective customer asks.'],['Content and publishing','Agree copy responsibilities, editing access, image rights and how routine updates will be published.'],['Search and enquiry foundations','Include descriptive metadata, crawlable links, meaningful error pages and a tested form destination.']],
  [['Agree the audience and offer','Choose the services and customer questions each page will answer. Inventory existing URLs so useful content and links can be preserved.'],['Review real page content','Test the navigation and mobile enquiry journey with actual headings, descriptions and available business evidence.'],['Check launch essentials','Review redirects, indexability, contact handling and editor access. Document hosting, domain ownership and future update responsibilities.']],
  [['Do we need a CMS?','A CMS helps when non-developers update services, articles or team information regularly. A smaller site with infrequent changes may need a simpler publishing workflow.'],['Will a new website automatically get traffic?','No. Public accessibility and useful content provide a foundation, while demand, competition, authority and ongoing improvement influence organic discovery.'],['Can we keep our domain and existing content?','Yes, subject to access and ownership. Review current URLs, redirect needs and content accuracy before changing the structure.']]),
 'web-applications':page('Custom Web Application Development',
  'Build a browser-based tool for bookings, approvals, customer accounts or internal operations, with the permissions and business rules the workflow requires.',
  'A web application is useful when visitors need to do something beyond reading pages. The important decisions are the state of each record, who can change it and what happens when an action fails or is repeated.',
  [['Workflow and data model','Define records, statuses, validations and the rules connecting customers, staff and administrators.'],['Accessible application screens','Plan forms, account states, search, notifications and recovery paths for keyboard and mobile users.'],['Services and integrations','Scope APIs, authentication, background work and external connections with explicit failure handling.']],
  [['Trace the task end to end','Identify inputs, approvals and outputs. Walk through cancellations, duplicate submissions and incomplete information before choosing a framework.'],['Deliver a working vertical slice','Connect one complete screen-to-database journey, including permissions and error states, before adding secondary features.'],['Verify the release workflow','Exercise realistic user roles, integration failures and data recovery. Hand over deployment notes and an agreed maintenance plan.']],
  [['When is a web app better than a mobile app?','A web app suits workflows reached through links and used across many devices. Device features, offline requirements and distribution may justify a mobile app instead.'],['Can you extend an existing application?','We first assess the code, dependencies, data model and release process. The findings determine whether a focused extension or a larger refactor is practical.'],['What determines the project scope?','User roles, business rules, connected systems and exceptions usually matter more than the number of screens. Bring a complete example of the task.']]),
 'cms-development':page('CMS Development & Content Management',
  'Give editors a reliable way to create, review and publish website content without changing code for every update.',
  'Choose the content model before choosing the editor. Reusable services, articles, authors and navigation need clear fields and relationships; a page builder alone does not establish editorial governance.',
  [['Structured content','Define reusable content types, required fields, media guidance and meaningful previews for editors.'],['Publishing permissions','Scope draft, review and publishing access, including who can change navigation and search metadata.'],['Migration and delivery','Map old content, URL rules and frontend delivery, with redirects where page addresses change.']],
  [['Inventory content and contributors','Document what is published, who maintains it and how often it changes. Identify repeated content that should have one source.'],['Test the editorial workflow','Prototype article creation, media selection and review using the team’s own material rather than empty example fields.'],['Migrate and train editors','Check links and formatting, reconcile imported records and hand over publishing guidance with permissions configured.']],
  [['Should we use a headless CMS?','It can suit content shared across several frontends. A conventional CMS may be simpler when the website is the only publishing channel.'],['Can editors manage SEO fields?','Yes, the agreed content model can include titles, descriptions, slugs and social previews, with validation and clear ownership.'],['Can we migrate from our current CMS?','First check export access, content relationships, media rights and URL history. A sample migration reveals formatting and redirect work early.']]),
 'api-backend':page('API & Backend Development',
  'Build the services behind your application: authenticated APIs, business rules, database operations and reliable connections between systems.',
  'A backend must handle the cases the interface cannot prevent: repeated requests, expired credentials, conflicting updates and unavailable providers. We scope these behaviours as part of the service contract.',
  [['API contracts','Define endpoints, request validation, response formats, pagination and versioning with the teams consuming the API.'],['Data and access rules','Model ownership, permissions and transaction boundaries so records remain consistent when several actions happen together.'],['Integration resilience','Plan timeouts, retry rules, idempotency, event delivery and logs that help diagnose failures without exposing secrets.']],
  [['Map systems and ownership','Identify which system is authoritative for each field and what permissions the integration requires.'],['Implement and test the contract','Use representative requests, invalid inputs and provider failures to verify behaviour beyond the happy path.'],['Document operation and change','Provide API usage notes, credential rotation responsibilities and a release approach for changes that affect consumers.']],
  [['Can you work with an existing frontend?','Yes. Start with its current request contracts and authentication model so backend changes do not unexpectedly break the interface.'],['Are APIs always real time?','No. Batch jobs and queued events can be a better fit for reporting, imports and providers with strict request limits.'],['What access is needed to quote an integration?','Provider documentation, sandbox access where available, sample payloads and the required read/write permissions help establish feasibility.']]),
 'ios-android-apps':page('iOS & Android App Development',
  'Plan mobile applications around the actions people need on their phones, with deliberate choices about device features, permissions and app-store distribution.',
  'The platform decision depends on the experience: camera use, background activity, offline work and device integrations can change the implementation. Define those requirements before comparing native and shared-code approaches.',
  [['Mobile task design','Scope navigation, input, notifications and accessible touch interactions for the primary on-the-go journey.'],['Device and service connections','Assess camera, location, authentication, backend APIs and the permissions each feature needs.'],['Release preparation','Plan signing accounts, store materials, privacy disclosures, supported OS versions and update ownership.']],
  [['Validate the mobile use case','List the devices, connectivity conditions and tasks users will encounter. Identify what must work without a network.'],['Prototype the difficult interaction','Test the device feature or service dependency with the highest uncertainty before building every screen.'],['Prepare a staged release','Check permissions, upgrades and account recovery on the agreed devices. Allow for store review and follow-up fixes.']],
  [['Do we need separate iOS and Android builds?','That depends on device requirements and the existing team. Native and cross-platform approaches have different tradeoffs; neither is best for every project.'],['Who owns the app-store accounts?','Ownership and access should be agreed before release. Client-controlled accounts help keep distribution and future updates with the business.'],['Can you guarantee app-store approval?','No. Review decisions belong to the stores. Submission preparation, policy checks and a response plan reduce avoidable rework.']]),
 'flutter-react-native':page('Flutter & React Native Development',
  'Explore a shared-code mobile application when the same customer journey needs to work on iOS and Android with a manageable release process.',
  'Cross-platform development can share substantial application logic, but platform testing and some native work remain necessary. Compare Flutter and React Native against your existing skills, required libraries and device interactions.',
  [['Framework assessment','Evaluate UI requirements, package support and existing code against a representative part of the application.'],['Shared application logic','Design navigation, data access and state handling so shared features stay consistent across platforms.'],['Platform-specific work','Allow for native modules, permissions, builds and testing where iOS and Android behave differently.']],
  [['Check dependencies before committing','Identify payments, maps, authentication and device SDKs, then verify that the chosen approach can support them.'],['Build a representative feature','Exercise navigation, network failures and a required native interaction on both target platforms.'],['Establish repeatable releases','Document signing, build configuration, dependency updates and platform regression checks.']],
  [['Does one codebase remove all native development?','No. Device SDKs, OS-specific behaviours and build configuration may still require platform expertise.'],['Can you continue an existing Flutter or React Native app?','An initial review checks dependency health, architecture, automated coverage and the effort needed to produce a working release.'],['How should we choose between the frameworks?','Use the required integrations, interaction design, team experience and long-term maintenance needs rather than a generic popularity ranking.']]),
 'progressive-web-apps':page('Progressive Web App Development',
  'Add app-like capabilities to a web experience where browser access, a shareable URL and selective offline support fit the user’s task.',
  'A progressive web app builds on the web rather than replacing it. Installability, notifications and background capabilities vary by browser and operating system, so the core journey should remain useful without optional features.',
  [['Reliable web foundation','Make the main task responsive, accessible and usable through ordinary browser navigation.'],['Offline and caching strategy','Choose which screens and data can be cached, how updates reach devices and what happens to actions made offline.'],['Optional app capabilities','Assess installation, push and device APIs against the browsers your audience actually uses.']],
  [['Define the connectivity problem','Separate read-only offline content from actions that need a server response. Identify sensitive data that should not remain on a device.'],['Test caching and synchronisation','Exercise lost connections, stale content, sign-out and conflicting changes rather than testing only a fresh online session.'],['Release progressive enhancements','Check the baseline experience and add supported capabilities with clear fallbacks and update behaviour.']],
  [['Can a PWA replace our native app?','It may suit browser-first workflows. Deep device integration or dependable background behaviour can favour a native or cross-platform application.'],['Will everything work offline?','Only features explicitly designed for it. Transactions, fresh inventory and authenticated server actions may still require a connection.'],['Does every browser support the same features?','No. Verify installation, notifications and device access against current platform support before promising them to users.']]),
 'mvp-development':page('MVP Development for Startups',
  'Build one complete product journey that tests a specific customer assumption, with scope and success criteria agreed before development.',
  'An MVP should answer a question: will a defined user complete, return to or pay for this workflow? If a manual service or clickable prototype can answer it, use that evidence before paying for a larger application.',
  [['Discovery and scope','Write the customer, problem, riskiest assumption and essential journey in a short brief with explicit exclusions.'],['Working first release','Build the minimum functional experience, including the access controls and recovery the task requires.'],['Learning and handover','Plan useful events, user feedback and a review that decides whether to continue, change direction or stop.']],
  [['Choose the assumption to test','Bring interview notes, sketches or the existing workaround. Identify what would invalidate the idea and the smallest credible test.'],['Deliver in working milestones','Review one complete flow at each milestone. Keep secondary features in a separate backlog rather than stretching the launch scope.'],['Evaluate with real users','Compare observed behaviour with the agreed threshold. Record the next decision and the technical work needed if the pilot expands.']],
  [['How long will an MVP take?','The answer depends on the journey, integrations and review needs. A schedule follows a scoped discovery discussion; a fixed week count without those details would be unreliable.'],['Can AI help us build the MVP?','It can assist drafting, prototyping and development. Real user validation, access controls and testing still need deliberate human decisions.'],['What is not optional in a minimum product?','Required security, data handling and the ability to complete the core task. Reduce feature breadth rather than removing controls the use case needs.']]),
 'saas-engineering':page('SaaS Engineering & Product Improvement',
  'Extend an existing SaaS product with maintainable features, safer releases and technical improvements informed by real customer workflows.',
  'SaaS engineering starts from a running product and its constraints. We assess current architecture, release friction and support problems before recommending feature work or refactoring. New platform creation belongs in SaaS platform development.',
  [['Product extensions','Scope customer-facing features against the existing tenant model, entitlements and backward compatibility.'],['Architecture improvements','Identify slow queries, fragile dependencies and tightly coupled modules with measurable reasons to change them.'],['Release and support tooling','Improve checks, migration procedures, operational visibility and administrator actions that reduce recurring support work.']],
  [['Review the running product','Inspect deployment, dependencies, issue history and the workflows most affected by defects or delays.'],['Improve one measurable bottleneck','Agree acceptance checks for a feature or refactor and release it in a small, reversible change.'],['Establish a sustainable cadence','Document architectural decisions, migration safety and the ongoing product backlog with the existing team.']],
  [['Do you need to rewrite our SaaS product?','Usually that is not the first step. Incremental changes may remove the main constraints while preserving working customer journeys.'],['Can you join our engineering team?','Collaboration can be scoped around the current repository, review practices, environments and release responsibilities. Availability and the engagement model are agreed separately.'],['How do we protect existing subscribers?','Use compatible interfaces, representative tenant tests, rehearsed migrations and a rollout plan that can detect and limit regressions.']]),
 'product-modernisation':page('Software Product Modernisation',
  'Improve an existing application’s usability, maintainability or infrastructure while preserving the business workflows people depend on.',
  'Modernisation is a risk-management decision as much as an engineering project. Start with the cost of the current limitations and the parts that already work; replacing everything at once can add migration risk without solving the most expensive problem.',
  [['Application assessment','Review dependencies, data flows, deployment and the workflows most exposed to defects or unsupported components.'],['Incremental replacement','Define boundaries for upgrading a module, interface or service without forcing every customer to move at once.'],['Migration and continuity','Scope data mapping, compatibility checks, rollback points and communication for affected users.']],
  [['Document the existing behaviour','Capture important rules, scheduled tasks and integrations before changing implementation. Use current records as reconciliation examples.'],['Modernise a bounded area','Select a slice with a clear benefit and test old and new behaviour side by side where practical.'],['Retire old dependencies deliberately','Confirm adoption, migrated records and operational ownership before removing the previous path.']],
  [['How do we choose between refactoring and rebuilding?','Compare the change required, existing test coverage, data migration and business continuity. A new codebase is not automatically the lower-risk option.'],['Can the product stay available during the work?','Continuity requirements influence the rollout. Some changes can run alongside the old path; others need an agreed maintenance window.'],['What do you need to assess the product?','Repository and environment access, architecture notes, known incidents, dependency information and examples of critical user tasks.']]),
 'user-experience':page('User Experience Design Services',
  'Understand where a customer journey becomes confusing, then prototype a clearer path before committing to production development.',
  'UX work begins with a task and the people completing it. Interviews, observed behaviour and support questions help separate a design preference from a problem that prevents progress.',
  [['Journey and task review','Map the steps, information and decisions in a priority journey, including drop-offs and support handoffs.'],['Information architecture','Organise navigation, labels and content around how users look for an answer or complete a task.'],['Prototypes and findings','Create testable flows and record what participants could complete, where they hesitated and what needs changing.']],
  [['Choose the research question','Agree the audience, available evidence and the decision the research should inform. Plan recruitment and consent for participant sessions.'],['Test a focused prototype','Use realistic tasks and content. Observe completion and misunderstanding rather than asking only whether people like the screens.'],['Translate findings into scope','Prioritise changes by severity and development effort, with annotated flows and unresolved questions for the delivery team.']],
  [['Is UX design the same as UI design?','UX covers the journey, structure and task behaviour. UI design develops the visual components and screen states used to express that journey.'],['Do we need a finished product for research?','No. Existing workflows, sketches and interactive prototypes can provide useful evidence before a product is built.'],['Can you guarantee higher conversion?','No. Research can identify friction and guide improvements; outcomes must be tested against actual behaviour and traffic.']]),
 'interface-design':page('User Interface Design Services',
  'Design clear product screens and reusable components so people can recognise actions, understand status and recover from mistakes.',
  'A useful interface system covers more than the ideal screen. Loading, validation, empty results, long content and restricted access all need deliberate presentation and clear language.',
  [['Screen and state design','Work through forms, lists, detail screens and the states required by the chosen customer journey.'],['Reusable components','Define buttons, inputs, typography and spacing with consistent behaviours and accessible interaction notes.'],['Developer handover','Provide assets, responsive rules and annotations that connect designs to actual application data.']],
  [['Inventory screens and constraints','Review brand foundations, user flows and the components already available in the codebase.'],['Design representative states','Prototype the most demanding screen and its smaller-screen layout before expanding the system.'],['Review implementation details','Resolve keyboard focus, text overflow, validation and component variants with the engineers building the interface.']],
  [['Can you use our existing design system?','Yes. Review its components and gaps first, then extend it where the product needs an additional state or pattern.'],['Does interface design include a brand identity?','Not automatically. Product styling can follow your current identity; new brand strategy, logos or identity guidelines need their own scope.'],['How is accessibility handled?','Design review can cover contrast, hierarchy, labels, focus and error communication. Implementation and assistive-technology testing are also needed.']]),
 'brand-visual-design':page('Brand & Visual Design Services',
  'Create a coherent visual identity for your website, product and communications, with practical rules your team can apply consistently.',
  'Brand design should make the business recognisable without making the product harder to use. We clarify the audience, positioning and existing identity assets before proposing a visual direction.',
  [['Identity direction','Explore typography, colour, imagery and graphic treatments against the audience and the business message.'],['Digital applications','Apply the direction to representative website, product or campaign touchpoints rather than isolated mood boards.'],['Usage guidance','Document approved assets, spacing, colour use and examples so later work follows the same decisions.']],
  [['Audit the existing identity','Collect current logos, source files, usage rights and examples of inconsistent application. Decide what should be retained.'],['Review a grounded visual direction','Evaluate the identity in realistic layouts, with actual content and accessibility constraints.'],['Package the agreed assets','Hand over the scoped formats, templates and usage notes, including licensing and any third-party asset restrictions.']],
  [['Can we keep our current logo?','Yes. A visual refresh can improve typography, layout and consistency while preserving a recognisable identity.'],['Are naming and trademark checks included?','Only if expressly scoped with suitable expertise. A design handover alone does not establish trademark clearance.'],['What should we bring to the first discussion?','Existing brand files, audience information, key messages and examples of where the identity must work.']]),
 'shopify-development':page('Shopify Development Services',
  'Build or improve a Shopify storefront around your catalogue, merchandising and fulfilment workflow, with a clear plan for themes, apps and integrations.',
  'Shopify can reduce infrastructure management, but app costs, platform limits and operational fit still matter. We evaluate your required buying journey before choosing theme changes, extensions or a more involved storefront.',
  [['Storefront and product journeys','Scope collection navigation, product templates, search and mobile shopping using representative products and variants.'],['Commerce integrations','Assess inventory, shipping, payments and business-system connections, including provider permissions and synchronisation failures.'],['Migration and launch checks','Plan products, customers, redirects and order handling; verify data fields and provider limitations before moving a store.']],
  [['Map the catalogue and operations','List product types, markets, fulfilment rules and recurring app fees. Identify the requirement that standard configuration cannot satisfy.'],['Build the hardest shopping path','Prototype selection, cart and the checkout-related change early. Availability of checkout customisation depends on the extension surface and plan.'],['Rehearse the store launch','Check test orders, stock updates, notifications, redirects and editor tasks before handing over the store.']],
  [['Can every checkout change be built on Shopify?','No. Available checkout extension surfaces and plan eligibility constrain customisation. Verify the exact requirement against current Shopify documentation before agreeing scope.'],['Can you migrate from WooCommerce?','Migration needs product and variant mapping, customer-data checks and a redirect plan. Historical orders and customer access depend on the supported migration approach.'],['What contributes to ongoing cost?','The Shopify plan, paid apps, payment arrangements, integration services and ongoing development. Compare the full operating cost rather than only the theme build.']]),
 'woocommerce-development':page('WooCommerce Development Services',
  'Create or improve a WordPress commerce store with product structures, checkout behaviour and editorial control suited to your business.',
  'WooCommerce offers flexibility, while hosting, extensions and updates need active ownership. The scope should account for theme quality, plugin compatibility and the day-to-day work of the store team.',
  [['Catalogue and storefront','Plan categories, variations, product content and the shopping experience around actual catalogue complexity.'],['Extensions and integrations','Choose required payment, shipping and business-system connections while reviewing compatibility and maintenance.'],['Hosting and release care','Define staging, backups, update checks and performance investigation so store changes can be tested before release.']],
  [['Review the WordPress environment','Inventory themes, plugins, hosting constraints and existing orders. Identify duplicated plugins and unsupported customisations.'],['Build against realistic orders','Test product options, taxes and shipping rules relevant to the intended market with payment-provider test modes.'],['Prepare editor and maintenance handover','Agree catalogue ownership, backup verification and the process for testing extension updates.']],
  [['Is WooCommerce free to run?','The core software does not remove operating costs. Hosting, extensions, payment fees, maintenance and custom development still need budgeting.'],['Can we keep our WordPress content?','Often, yes. Review the theme, URLs and content relationships so commerce work preserves useful editorial pages.'],['What if our plugins conflict?','Use a staging environment to reproduce the issue and narrow down the interaction. Reducing overlapping plugins may be more reliable than adding another workaround.']]),
 'custom-ecommerce':page('Custom Ecommerce Development',
  'Build a tailored commerce workflow when essential product, pricing or ordering rules cannot be handled sensibly by a standard store.',
  'Custom commerce adds flexibility and operational responsibility. Before building, compare a conventional platform with focused extensions against a custom solution for the specific requirement that differentiates the business.',
  [['Specialised buying rules','Model configurations, customer-specific pricing, quote requests or approval paths that define the purchase.'],['Order and stock systems','Establish order states, inventory authority and reconciliation between the storefront and fulfilment tools.'],['Commerce operations','Plan administration, payment-provider integration, refunds and monitoring alongside the customer screens.']],
  [['Validate the exceptional requirement','Prototype the configuration, B2B approval or pricing rule that makes a standard platform unsuitable.'],['Connect the order lifecycle','Follow order creation through payment status, allocation, fulfilment and cancellation, including duplicate events.'],['Test recovery before launch','Rehearse failed payments, stale stock and interrupted provider connections with clear staff recovery procedures.']],
  [['Should we build our own payment processing?','Use appropriate payment providers and their supported integration patterns. A custom store does not mean inventing a payment infrastructure.'],['When is headless commerce appropriate?','It can help when distinct frontends need a shared commerce backend. It also adds integration and deployment responsibilities that should justify the added complexity.'],['How do you estimate custom ecommerce?','Product rules, order states, customer roles, integrations and migration determine scope. A catalogue sample and fulfilment walkthrough are useful starting points.']]),
 'web-mobile-testing':page('Web & Mobile Application Testing',
  'Check the customer journeys that matter across agreed browsers and devices, with reproducible reports the delivery team can act on.',
  'Functional QA should cover what people actually do: register, submit, buy, approve or recover an account. A risk-based plan gives important workflows more attention than a long list of superficial checks.',
  [['Journey-based coverage','Define expected outcomes, roles and failure states for the flows most important to the product.'],['Browser and device matrix','Select representative browsers, operating systems and screen sizes based on the audience and support commitments.'],['Actionable defect reports','Record steps, test data, environment and observed behaviour, with severity tied to the user impact.']],
  [['Agree release risks','Review requirements, recent changes and prior incidents. Identify which failures would block release or require a workaround.'],['Run exploratory and scripted checks','Exercise normal tasks, boundary inputs, interrupted sessions and relevant accessibility interactions.'],['Retest and report residual risk','Verify fixes and rerun affected journeys. Summarise what was tested, what remains open and the coverage limits.']],
  [['Can you test without written requirements?','Exploratory review can begin from a working product, but expected behaviour still needs agreement with an owner before defects can be judged consistently.'],['Will testing find every bug?','No. A report should make its environments, coverage and limits explicit rather than imply complete certainty.'],['Does this include automated tests?','Automation is a separate choice based on repeatability and maintenance value. Manual investigation remains useful for new or changing behaviour.']]),
 'test-automation':page('Test Automation Services',
  'Create maintainable automated checks for stable, important product behaviour so changes can be evaluated during development and release.',
  'The best first automation target is a repeatable risk, not the largest possible test suite. Choose the layer that can detect the problem reliably: unit, API, integration or browser testing.',
  [['Coverage strategy','Identify the behaviours worth repeating and place checks at the simplest effective level.'],['Stable test data','Plan fixtures, isolated accounts and environment setup so results do not depend on yesterday’s activity.'],['Pipeline reporting','Connect useful checks to the release workflow with clear failure diagnostics and ownership.']],
  [['Assess the current release process','Review existing tests, manual regression work and the failures that have reached production.'],['Automate a small high-value set','Add meaningful assertions, controlled data and failure evidence. Address flaky behaviour before expanding coverage.'],['Hand over maintenance practices','Agree how tests change with features, which failures block release and who investigates an unstable check.']],
  [['Should every UI action be automated?','No. Tests that mirror every interaction can be expensive to maintain. Cover important outcomes and use lower-level checks where they are clearer and more reliable.'],['Can automation replace manual QA?','It can repeat known checks efficiently. Exploratory testing and evaluation of new behaviour still require human judgment.'],['What makes a test suite trustworthy?','Deterministic data, meaningful assertions, manageable runtime and failures that identify a real issue rather than environment noise.']]),
 'performance-api-testing':page('Performance & API Testing Services',
  'Evaluate API behaviour and application response under agreed workloads, with findings tied to a realistic usage model and observable limits.',
  'A useful performance test states its assumptions: request mix, concurrent activity, data volume and environment. A large request count without this context does not establish production readiness.',
  [['API behaviour checks','Exercise authentication, validation, pagination, permissions and invalid requests against the agreed contract.'],['Load scenarios','Define expected usage, bursts and slow dependencies, with response-time and error-rate targets.'],['Bottleneck investigation','Correlate failures and slow requests with application logs, queries and infrastructure measurements where available.']],
  [['Agree the workload and boundaries','Confirm permission to test, a suitable environment, provider limits and stop conditions before generating load.'],['Run a controlled baseline','Use representative data and repeatable scenarios. Separate application behaviour from test-environment constraints.'],['Verify the improvement','Retest the affected scenario after changes and document capacity findings with their assumptions and remaining uncertainty.']],
  [['Can you test our production API?','Only with explicit operational agreement, suitable controls and provider permissions. A representative non-production environment is often the safer first step.'],['Does a fast API mean a fast website?','Not necessarily. Frontend rendering, network conditions and large assets can affect user experience independently of API response time.'],['What will the report include?','Workload definitions, environment details, latency and error observations, reproducible failures and prioritised investigation notes.']]),
 'cloud-deployment':page('Cloud Deployment Services',
  'Prepare application hosting, environment configuration and a repeatable release path matched to your workload and the people operating it.',
  'Choose hosting from application needs: runtime support, data location, background jobs, scaling behaviour and operating cost. The simplest environment that meets those needs is often easier to maintain than a complex infrastructure stack.',
  [['Environment planning','Define development, staging and production boundaries, runtime requirements and configuration ownership.'],['Data and credentials','Plan database access, secret management, backup responsibilities and connectivity between services.'],['Operational readiness','Scope domain configuration, health checks, logs and recovery steps alongside the initial deployment.']],
  [['Assess the application runtime','Check build commands, persistent storage, scheduled work and external dependencies before choosing a hosting approach.'],['Deploy a representative environment','Validate configuration, database changes and service connections with realistic request paths.'],['Rehearse release and recovery','Document how to deploy, detect failure and restore the agreed previous state or recover from backup.']],
  [['Which cloud provider should we choose?','Compare runtime fit, regional requirements, support, cost and your existing expertise. Provider choice should follow these constraints.'],['Are backups enough for recovery?','No. Recovery also depends on retention, access and tested restoration steps. Agree the acceptable loss and recovery window.'],['Can you migrate our existing hosting?','A migration starts with dependencies, data volume, DNS and downtime requirements, followed by a rehearsal and a cutover plan.']]),
 'ci-cd-pipelines':page('CI/CD Pipeline Development',
  'Connect code changes, meaningful checks and deployment steps so releases follow a visible, repeatable process.',
  'A pipeline should make a release easier to understand and recover. Its checks, permissions and approval gates must reflect the risk of the application rather than adding steps without a purpose.',
  [['Build and verification','Define reproducible builds, dependency handling and checks that reveal meaningful regressions.'],['Environment promotion','Separate credentials and configuration, with explicit approval where a production change requires review.'],['Release diagnosis','Provide logs, artifact references and a documented response when a deployment fails.']],
  [['Map the manual release','Record commands, accounts and undocumented dependencies in the current process. Identify steps that rely on one person.'],['Automate a staging deployment','Validate builds and application checks in a representative environment before enabling production promotion.'],['Exercise failed-release handling','Test missing configuration, failed checks and database-change behaviour so the team knows when to stop or recover.']],
  [['Does continuous delivery mean automatic production releases?','No. A pipeline can prepare a verified release while retaining an explicit production approval.'],['Can you use our existing repository tools?','The design should start from the current repository, runner permissions and hosting interfaces rather than force an unnecessary tool migration.'],['Can every deployment be rolled back?','Not automatically. Database and external-system changes need specific compatibility or recovery strategies.']]),
 'maintenance-monitoring':page('Software Maintenance & Monitoring',
  'Keep visibility into application health, dependency changes and recurring faults with an agreed maintenance scope and response process.',
  'Maintenance needs clear boundaries: what is monitored, who receives alerts and which work is covered. Monitoring creates value when a signal leads to an understood action instead of a growing inbox of noise.',
  [['Health and error visibility','Choose uptime checks, application errors and operational signals that match the critical user journeys.'],['Updates and change review','Plan dependency updates, environment changes and regression checks using a staging workflow.'],['Incident and support ownership','Document escalation contacts, access arrangements and the difference between a defect, an operational incident and a new feature.']],
  [['Establish a service inventory','List applications, providers, owners and renewal or update dependencies. Review known incidents and current monitoring gaps.'],['Define useful alerts','Set actionable thresholds and verify who receives each alert. Add concise diagnosis and recovery notes.'],['Review maintenance regularly','Summarise incidents, completed updates and unresolved risks so future improvements have an explicit priority.']],
  [['Is round-the-clock support included?','Coverage hours, response targets and escalation arrangements are contractual choices. They must be agreed rather than assumed.'],['Can you maintain software you did not build?','A handover review checks repository access, deployment, dependencies and known issues before agreeing ongoing responsibility.'],['Does maintenance include new features?','Only where included in the engagement. Separate routine upkeep and incident work from product development to keep expectations clear.']]),
 'smart-contracts':page('Smart Contract Development',
  'Explore on-chain agreement logic only where shared execution or verifiable state provides a practical advantage over a conventional application.',
  'Smart contracts introduce irreversible actions, transaction costs and key-management risks. Define the participants, trust assumptions and failure consequences before choosing a chain or writing contract logic.',
  [['Rules and state transitions','Model the permitted actions, ownership and conditions that move an agreement from one state to another.'],['Application integration','Plan transaction preparation, confirmation states and how the interface explains failures or rejected signatures.'],['Testing and review scope','Exercise permissions, edge cases and upgrade behaviour, with independent security review scoped separately where needed.']],
  [['Validate the need for on-chain execution','Compare a database and signed audit records with the proposed contract. Identify what must be independently verifiable.'],['Prototype with test assets','Review state transitions, roles and exceptional paths on a suitable test environment before any mainnet decision.'],['Plan operational control','Agree key custody, emergency procedures and the release-review responsibilities appropriate to the contract’s risks.']],
  [['Does development include a security audit?','An independent security audit is a distinct engagement unless explicitly included. Development testing is not a substitute for independent assurance.'],['Can a deployed contract be changed?','Only according to its design and governance. Upgrade mechanisms add their own trust and access risks.'],['Can blockchain guarantee the input is true?','No. On-chain execution cannot by itself verify that off-chain records or events are accurate.']]),
 'web3-applications':page('Web3 Application Development',
  'Design understandable wallet and transaction journeys for applications that need to interact with blockchain networks.',
  'Web3 usability depends on helping people understand what they are signing, which network they are using and whether an action has actually completed. Clear transaction states matter as much as the wallet connection button.',
  [['Wallet and account flows','Scope connection, disconnection, network changes and the boundaries between wallet identity and application accounts.'],['Transaction interfaces','Show proposed actions, confirmation progress and recoverable errors without implying that pending activity is complete.'],['Read models and services','Plan how contract data, indexing and conventional backend services support usable application screens.']],
  [['Map the trust boundaries','Identify custody, supported networks, provider dependencies and which actions require a signature.'],['Test the full transaction journey','Exercise rejected signatures, disconnected wallets, wrong networks and delayed confirmations using test assets.'],['Prepare support and release guidance','Document supported wallets, transaction diagnosis and handling for provider or network failures.']],
  [['Does a user need cryptocurrency for every action?','It depends on the network and transaction design. Fees and any sponsored-transaction arrangement should be explicit in the product scope.'],['Can you recover a user’s lost wallet?','Recovery depends on the wallet and custody model. A non-custodial application cannot assume control over a user’s private keys.'],['Is a Web3 app entirely on-chain?','Usually not. Interfaces, content and indexing often rely on conventional services whose reliability and access controls still matter.']]),
 'traceability-solutions':page('Supply Chain Traceability Software',
  'Connect product, batch and custody events so authorised teams can follow a record through the supply chain and investigate exceptions.',
  'Traceability starts with identifiers and reliable event capture. A shared ledger may help in some partner arrangements, but it cannot repair inconsistent source data or prove that a physical event was recorded truthfully.',
  [['Identifiers and event model','Define products, lots, locations and custody events with rules for corrections and missing information.'],['Partner data capture','Scope scanning, imports and integrations around the tools and connectivity each participant can support.'],['Search and investigation','Plan record lookup, affected-batch views and access permissions for operational review.']],
  [['Map a single product journey','Follow one batch through the participants and note where identifiers or evidence are lost.'],['Pilot event capture','Use realistic handoffs to test duplicate scans, delayed submissions and incorrect records.'],['Review reconciliation and governance','Agree who can enter, correct and view data, and how conflicting partner records are resolved.']],
  [['Do we need blockchain for traceability?','Not always. A conventional database with controlled access and an audit trail may meet the need with less operational complexity.'],['Can we use QR codes or barcodes?','They can identify records, but the capture process and validation determine the quality of the resulting trace.'],['Will this certify regulatory compliance?','No. Applicable obligations and required evidence need to be identified with appropriate domain expertise and explicitly included in scope.']]),
 'search-engine-optimisation':page('On-page SEO & Content Optimisation',
  'Improve existing service and article pages so their titles, headings, answers and internal links explain the offer more clearly to people and search engines.',
  'This service focuses on page-level implementation. For a broader crawling, indexing and measurement strategy, use our SEO, AEO and GEO service. The work begins with an inventory and a defined customer question, not a list of repeated keywords.',
  [['Page intent and content gaps','Assign each page a distinct purpose and identify missing information, repetitive sections and weak service explanations.'],['Metadata and headings','Write descriptive titles and summaries that match visible content, with useful section headings and accurate claims.'],['Contextual internal links','Connect related guides, specialist services and relevant examples using descriptive link text.']],
  [['Review existing evidence','Use available search-query data, current URLs and customer questions to prioritise pages that can serve the business.'],['Rewrite and implement focused changes','Replace generic copy with decision criteria, scope and useful answers. Preserve working URLs unless a justified consolidation needs a redirect.'],['Verify and compare','Check rendered content, links and indexability, then compare the agreed performance baseline over suitable date ranges.']],
  [['Will adding keywords improve every page?','No. A page needs to meet a distinct search need and provide a useful answer. Repetition can make it harder to read without adding value.'],['Do all pages need long copy?','No. Depth should follow the question. A concise contact page and a detailed comparison article serve different purposes.'],['Can you guarantee a ranking increase?','No. Implementation is controllable; rankings and clicks also depend on demand, competition, authority and search-system decisions.']]),
 'content-campaigns':page('Content Strategy & Campaign Planning',
  'Build a content plan around the questions buyers ask, the evidence your business can provide and a measurable next step.',
  'A useful campaign connects a specific audience, message, landing page and follow-up process. Publishing more material without a defined offer or distribution plan is unlikely to resolve a weak customer journey.',
  [['Audience and question map','Organise sales questions, objections and search opportunities around the services the business actually delivers.'],['Editorial and campaign briefs','Define the purpose, evidence, format and intended action for each asset before production.'],['Landing and follow-up alignment','Connect campaign messages with relevant pages and an enquiry route that captures useful context.']],
  [['Audit the message and evidence','Review existing content, customer questions and approved examples. Identify claims that need support before publication.'],['Plan a focused content sequence','Choose a small set of connected assets with clear responsibilities, review stages and distribution channels.'],['Measure useful engagement','Track relevant visits, next-step actions and lead fit rather than treating publishing volume as success.']],
  [['Does this include running paid ads?','Channel execution, media spend and account management need explicit scope. Content planning alone does not imply paid campaign management.'],['Can AI write the content?','AI can assist drafting and organisation, but subject knowledge, factual checks and business evidence need accountable review.'],['How should we choose article topics?','Start with genuine buyer questions and a relevant commercial destination. Validate search demand and competing answers where data is available.']]),
 'conversion-optimisation':page('Website Conversion Optimisation',
  'Investigate where relevant visitors struggle to enquire, book or buy, then test focused improvements to the customer journey.',
  'Conversion work needs a defined outcome and trustworthy measurement. First distinguish a confusing interface from poor traffic fit, a weak offer or a broken form; each calls for a different response.',
  [['Journey and measurement review','Check key events, form behaviour and the path from landing page to completed action.'],['Friction investigation','Use available analytics, support questions and observed tasks to identify unclear information or unnecessary steps.'],['Experiment and release plan','Define a hypothesis, primary measure and rollout decision before changing the experience.']],
  [['Verify the baseline','Confirm that completions and failures are recorded correctly and separate relevant audience segments where practical.'],['Prioritise a specific obstacle','Choose a change supported by evidence, such as clearer requirements, better error guidance or a shorter booking path.'],['Evaluate the outcome','Use an appropriate experiment or a clearly qualified before-and-after comparison, accounting for traffic and campaign changes.']],
  [['Do we need enough traffic for an A/B test?','Yes, the detectable effect and traffic volume determine whether a test can answer the question. Lower-traffic sites may benefit first from usability research and obvious defect fixes.'],['Does a higher conversion rate always mean better leads?','No. Track lead quality and business outcomes alongside form completion so the design does not simply attract irrelevant submissions.'],['Can you promise a percentage uplift?','No. A proposed change is a hypothesis until evaluated with suitable evidence.']]),
 '2d-games':page('2D Game Development',
  'Develop a focused 2D game around responsive controls, understandable rules and a playable core loop for the chosen platform.',
  'A game should become playable early. Testing the central interaction with simple assets reveals more about the concept than building menus and progression before the mechanic is enjoyable.',
  [['Playable prototype','Define movement, interaction, feedback and the win or loss conditions that demonstrate the core loop.'],['Content and game systems','Scope levels, progression, saved state and difficulty based on what the first playable test reveals.'],['Platform preparation','Plan input methods, aspect ratios, performance and distribution requirements for web, desktop or mobile.']],
  [['Write a small game brief','Agree the audience, session length, reference controls and the mechanic that needs validation.'],['Playtest the core loop','Observe whether players understand the goal and controls. Adjust feedback and difficulty before expanding content.'],['Prepare the release build','Check devices, save behaviour and packaging, with content licensing and future update ownership agreed.']],
  [['Is art and audio included?','Asset creation, licensing and the number of required animations or sound effects must be included explicitly in the scope.'],['Can the game run in a browser?','That depends on the engine, performance and input requirements. Test a representative build on the intended browsers early.'],['Can you guarantee a successful game launch?','No. Development can deliver agreed behaviour and quality checks; audience demand, distribution and commercial performance remain uncertain.']]),
 'interactive-experiences':page('Interactive Experience Development',
  'Create a purposeful interactive tool, learning activity or branded experience that helps people understand an idea by taking part.',
  'Interaction should serve the message. A product explorer, training scenario or campaign game needs a clear task, usable controls and an accessible way to reach the useful information.',
  [['Interaction concept','Define what participants choose or manipulate and how that action explains the product, lesson or campaign message.'],['Responsive experience','Scope input, feedback and alternatives across the devices and accessibility needs of the audience.'],['Publishing and measurement','Plan embedding, hosting, completion events and the handoff to a relevant next step.']],
  [['Choose the learning or business goal','Write what a participant should understand or do after the experience. Remove interactions that do not help that goal.'],['Prototype the key moment','Use a small working interaction to test instructions, feedback and comprehension with representative users.'],['Publish with useful fallbacks','Review loading, reduced motion, keyboard use and constrained devices before integrating the experience into its destination.']],
  [['Do interactive experiences always need game mechanics?','No. A clear comparison tool or guided product walkthrough can be more useful than points, timers or competition.'],['Can it be added to our existing website?','First check the host platform, embedding constraints and styling boundaries. The integration should preserve the surrounding page’s usability.'],['What should we measure?','Completion, understanding and the relevant next action. Time spent alone may indicate interest or confusion, so interpret it carefully.']])
};
